def compress(g):
    rows=[g[0]]
    for r in g[1:]:
        if r!=rows[-1]: rows.append(r)
    t=[[r[i] for r in rows] for i in range(len(g[0]))]
    cols=[t[0]]
    for c in t[1:]:
        if c!=cols[-1]: cols.append(c)
    return [list(r) for r in zip(*cols)]

